import { useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import Icon from "./Icon";

export default function Header({ dark, setDark, lang, setLang, search, setSearch }) {
  const searchRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    document.body.className = dark ? "dark" : "";
  }, [dark]);

  const handleSearch = (e) => {
    const value = e.target.value;
    setSearch(value);
    if (value) {
      navigate(`/books?search=${encodeURIComponent(value)}`);
    }
  };

  return (
    <header className="header">
      <div className="header-inner">
        <a href="/" className="logo">
          <div className="logo-icon">📖</div>
          <div className="logo-text">
            Islamic Knowledge Hub
            <small>Quran · Hadith · Books · Lectures</small>
          </div>
        </a>

        <div className="header-search">
          <Icon name="search" size={16} />
          <input
            ref={searchRef}
            type="text"
            placeholder="Search books, hadith, duas…"
            value={search}
            onChange={handleSearch}
          />
        </div>

        <div className="header-actions">
          <button className="hbtn" onClick={() => setDark(d => !d)}>
            <Icon name={dark ? "sun" : "moon"} size={15} />
            {dark ? "Light" : "Dark"}
          </button>
          <button className="hbtn gold" onClick={() => setLang(l => l === "en" ? "kin" : "en")}>
            <Icon name="globe" size={15} />
            {lang === "en" ? "Kinyarwanda" : "English"}
          </button>
        </div>
      </div>
    </header>
  );
}
